func count(x int64) int64 {
	var res int64 = 0
	// a < b, a,b positive integers
	// x = a*b - (a^2 + b^2)/2
	// 2x = 2ab - a^2 - b^2 = -(a-b)^2 + 2ab - a^2 - b^2 + (a-b)^2
	// We just brute-force a and solve quadratic for b.
	for a := int64(1); ; a++ {
		// minimal b is a+1
		b := a + 1
		// area for minimal b
		area := a*b - (a*a+b*b)/2
		if area > x {
			break
		}
		// we need to find b such that area <= x
		// area = a*b - (a^2 + b^2)/2
		// 2*area = 2ab - a^2 - b^2
		// For fixed a, area decreases when b grows large (due to -b^2/2 term),
		// so area is concave; we can just increment b until area <= x fails.
		for ; ; b++ {
			area = a*b - (a*a+b*b)/2
			if area <= 0 {
				break
			}
			if area > x {
				break
			}
			res++
		}
	}
	return res
