func count(x int64) int64 {
	var res int64 = 0
	var a int64
	for a = 1; a*a <= x; a++ {
		// b > a, and a*b <= x
		bmax := x / a
		if bmax <= a {
			continue
		}
		res += bmax - a
	}
	return res
}

