func isSquare(n int64) bool {
	if n < 0 {
		return false
	}
	x := int64Sqrt(n)
	return x*x == n
}

func int64Sqrt(n int64) int64 {
	if n <= 0 {
		return 0
	}
	x := n
	y := (x + 1) >> 1
	for y < x {
		x = y
		y = (x + n/x) >> 1
	}
	return x
}

func countSuitable(x int64) int64 {
	if x <= 0 {
		return 0
	}
	// a < b, a,b positive integers, x = a*b - (a^2 + b^2)/2
	// 2x = 2ab - a^2 - b^2 = -(a-b)^2 + 2ab
	// rearranged: (a-b)^2 + 2x = 2ab
	// Let d = b-a > 0, then b = a+d
	// x = a^2 + ad - d^2/2
	// 2x = 2a^2 + 2ad - d^2
	// For fixed d, quadratic in a: 2a^2 + 2da - (d^2 + 2x) = 0
	// Discriminant: Δ = 4d^2 + 8(d^2 + 2x) = 12d^2 + 16x
	// a integer if Δ is perfect square and (-2d + sqrtΔ) divisible by 4 and >0

	var cnt int64 = 0
	// d = b-a >=1
	// rough bound: from x = a^2 + ad - d^2/2 >= -d^2/2, but we need practical bound.
	// Use d up to sqrt( (4x)/3 ) + some margin; but safe bound: d^2 <= 2x + something.
	// From 2x = 2a^2 + 2ad - d^2 >= -d^2 => d^2 <= 2x
	// so d <= sqrt(2x)
	limit := int64Sqrt(2 * x)
	for d := int64(1); d <= limit; d++ {
		disc := 12*d*d + 16*x
		if !isSquare(disc) {
			continue
		}
		s := int64Sqrt(disc)
		// a = (-2d + s)/4 must be positive integer
		num := s - 2*d
		if num <= 0 || num%4 != 0 {
			continue
		}
		a := num / 4
		if a <= 0 {
			continue
		}
		b := a + d
		if a < b {
			cnt++
		}
	}
	return cnt
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var N int64
	fmt.Fscan(in, &N)

