import (
	"bufio"
	"fmt"
	"os"
)

func countX(x int64) int64 {
	var cnt int64 = 0
	for a := int64(1); a*a <= x; a++ {
		// b^2 = x + a^2 must be perfect square
		s := x + a*a
		// integer sqrt
		l, r := int64(1), s
		for l <= r {
			m := (l + r) >> 1
			msq := m * m
			if msq == s {
				// need b > a
				if m > a {
					cnt++
				}
				break
			} else if msq < s {
				l = m + 1
			} else {
				r = m - 1
			}
		}
	}
	return cnt
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var N int64
	fmt.Fscan(in, &N)

	// Binary search on x
	// upper bound: for each x there are at most about sqrt(x) pairs
	// N up to 1e9, x won't exceed about 1e18 safely
	var lo int64 = 1
	var hi int64 = 1
	for countX(hi) < N {
		hi <<= 1
		if hi > 1e18 {
			hi = 1e18
			break
		}
	}

	for lo < hi {
		mid := (lo + hi) >> 1
		if countX(mid) >= N {
			hi = mid
		} else {
			lo = mid + 1
		}
	}

	fmt.Println(lo)
}
